params = 7e9                          # a 7B-parameter model
gpus = 8
bytes_per_param = {"weights": 2, "grads": 2, "optimizer": 12}   # fp16 + Adam fp32 states

def per_gpu_gb(stage):
    w, g, o = (params * bytes_per_param[k] for k in ("weights", "grads", "optimizer"))
    if stage >= 1:
        o /= gpus                     # ZeRO-1: shard optimizer states
    if stage >= 2:
        g /= gpus                     # ZeRO-2: also shard gradients
    if stage >= 3:
        w /= gpus                     # ZeRO-3: also shard weights
    return round((w + g + o) / 1e9, 1)

memory = {f"ZeRO-{s}" if s else "DDP": per_gpu_gb(s) for s in range(4)}
for name, gb in memory.items():
    print(f"{name:7} {gb:6} GB per GPU", "(fits 80 GB)" if gb <= 80 else "")
